package org.slavicmyths.verify;
import java.util.*;
import java.nio.file.*;
import net.minecraft.server.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.*;
import net.minecraft.world.phys.Vec3;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.*;
import org.slavicmyths.yaga.*;
@EventBusSubscriber(modid="slavicmyths")
public final class NormalWorldProbe {
 static boolean enabled(){return Boolean.getBoolean("slavicmyths.repairNormal");}
 static long about,started,stopping,pre,peak,stageAt;static int phase,ticks,lastPhase=-1,siteIndex;static final String[] SITES={"sanctuary_unfading_fire","gorodishche","serpent_hill","abode_pure_spring"};static final java.util.List<Long> tickTimes=new ArrayList<>();static ServerPlayer player;
 static final Map<String,Object> metrics=new LinkedHashMap<>();
 static final class Connection extends net.minecraft.network.Connection {final io.netty.channel.embedded.EmbeddedChannel c=new io.netty.channel.embedded.EmbeddedChannel();Connection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public io.netty.channel.Channel channel(){return c;}}
 static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl {Listener(ServerPlayer p){super(p.server,new Connection(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}@Override public void send(net.minecraft.network.protocol.Packet<?> p){if(p instanceof net.minecraft.network.protocol.game.ClientboundSystemChatPacket chat)System.out.println("QA_MESSAGE "+chat.content().getString());}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener l){send(p);}}
 @SubscribeEvent public static void about(ServerAboutToStartEvent e){if(enabled()){about=System.nanoTime();metrics.put("scenario",System.getProperty("slavicmyths.repairScenario","bootstrap"));}}
 @SubscribeEvent public static void start(ServerStartedEvent e){if(!enabled())return;started=System.nanoTime();stageAt=started;metrics.put("world_load_ms",(started-about)/1_000_000);var nether=e.getServer().getLevel(Level.NETHER);boolean biome=nether.getChunkSource().getGenerator().getBiomeSource().possibleBiomes().stream().anyMatch(b->b.is(org.slavicmyths.navya.NavyaWorldgen.BIOME));metrics.put("navya_in_nether",biome);System.out.println("NORMAL_PROBE "+metrics);}
 @SubscribeEvent public static void pre(net.neoforged.neoforge.event.tick.ServerTickEvent.Pre e){if(enabled())pre=System.nanoTime();}
 @SuppressWarnings("unchecked") @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(!enabled()||started==0)return;long tickNanos=System.nanoTime()-pre;peak=Math.max(peak,tickNanos);tickTimes.add(tickNanos);ticks++;var server=e.getServer();var w=server.overworld();String scenario=System.getProperty("slavicmyths.repairScenario","bootstrap");if(phase!=lastPhase){lastPhase=phase;System.out.println("NORMAL_PROBE_PHASE "+phase+" "+metrics);}try{
  if(scenario.equals("bootstrap")){if(ticks==60)stop(server,"PASS");return;}
  if(System.nanoTime()-started>(scenario.equals("sites")?600_000_000_000L:240_000_000_000L)){stop(server,"FAIL timeout phase="+phase);return;}
  if(phase==0){player=new ServerPlayer(server,w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"GenerationQA"),ClientInformation.createDefault());player.connection=new Listener(player);player.setGameMode(GameType.CREATIVE);var at=w.getSharedSpawnPos();player.moveTo(at.getX()+.5,at.getY()+2,at.getZ()+.5,0,0);player.setNoGravity(true);w.addNewPlayer(player);var f=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");f.setAccessible(true);((Map<UUID,ServerPlayer>)f.get(server.getPlayerList())).put(player.getUUID(),player);phase=1;stageAt=System.nanoTime();if(scenario.equals("sites")){phase=10;org.slavicmyths.worldgen.LargeSiteJobs.create(player.createCommandSourceStack().withPermission(4),SITES[siteIndex]);}else if(scenario.equals("chud")){phase=3;String kind=System.getProperty("slavicmyths.chudKind","city");metrics.put("chud_kind",kind);org.slavicmyths.chud.ChudCreationJobs.create(player.createCommandSourceStack().withPermission(4),kind,r->{if(r==null){metrics.put("chud_failed",true);phase=99;}else{metrics.put("chud_ms",(System.nanoTime()-stageAt)/1_000_000);metrics.put("chud_entrance",r.entrance().toShortString());phase=4;}});}else if(!YagaDiscovery.create(player,null))throw new IllegalStateException("Yaga request refused");}
  else if(phase==10){var entry=org.slavicmyths.worldgen.ManualStructureRecords.get(w).entries().stream().filter(v->v.family().equals(SITES[siteIndex])).findFirst();if(entry.isPresent()){
   var site=entry.get();metrics.put(SITES[siteIndex]+"_ms",(System.nanoTime()-stageAt)/1_000_000);metrics.put(SITES[siteIndex]+"_distance",Math.sqrt(site.arrival().distSqr(player.blockPosition())));
   if(siteIndex==0){var at=site.arrival().offset(0,0,-19);var heart=(org.slavicmyths.sanctuary.SanctuaryHeart)w.getBlockEntity(at);if(heart==null||heart.instance==null)throw new IllegalStateException("Full sanctuary has no configured central brazier");player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(org.slavicmyths.sanctuary.SanctuaryContent.item("sacred_ember")));heart.interact(player,net.minecraft.world.InteractionHand.MAIN_HAND);if(!org.slavicmyths.sanctuary.SanctuaryRecords.get(w).restored(heart.instance))throw new IllegalStateException("Full sanctuary fire restoration failed");org.slavicmyths.guardians.GuardianWorld.ensure(w,heart.instance);var ledger=org.slavicmyths.guardians.GuardianLedger.get(w).row(heart.instance);metrics.put("fire_guardian_present",ledger.hasUUID("Boss")&&w.getEntity(ledger.getUUID("Boss"))!=null);metrics.put("full_fire_restored",true);}
   if(siteIndex==1){int villagers=w.getEntitiesOfClass(net.minecraft.world.entity.npc.Villager.class,new net.minecraft.world.phys.AABB(site.bounds().minX(),site.bounds().minY(),site.bounds().minZ(),site.bounds().maxX()+1,site.bounds().maxY()+1,site.bounds().maxZ()+1)).size();metrics.put("city_villagers",villagers);if(villagers==0)throw new IllegalStateException("City has no residents");}
   System.out.println("NORMAL_PROBE_SITE "+metrics);if(++siteIndex==SITES.length)stop(server,"PASS");else{stageAt=System.nanoTime();org.slavicmyths.worldgen.LargeSiteJobs.create(player.createCommandSourceStack().withPermission(4),SITES[siteIndex]);}
  }else{var f=org.slavicmyths.worldgen.LargeSiteJobs.class.getDeclaredField("JOBS");f.setAccessible(true);if(!((Map<?,?>)f.get(null)).containsKey(w))throw new IllegalStateException("Site queue stopped without "+SITES[siteIndex]);}}
  else if(phase==1){var d=YagaData.get(w);if(d.placed){metrics.put("yaga_ms",(System.nanoTime()-stageAt)/1_000_000);if(w.getEntity(d.npc)==null||w.getEntity(d.kuzya)==null)throw new IllegalStateException("Missing Yaga/Kuzya");phase=2;stageAt=System.nanoTime();if(org.slavicmyths.bayun.BayunCreation.create(player.createCommandSourceStack().withPermission(4))==0)throw new IllegalStateException("Bayun request refused");}else if(!YagaDiscovery.active(server))throw new IllegalStateException("Yaga stopped without a house");}
  else if(phase==2&&org.slavicmyths.bayun.BayunHomes.get(w).nearest(player.blockPosition())!=null){metrics.put("bayun_ms",(System.nanoTime()-stageAt)/1_000_000);phase=3;stageAt=System.nanoTime();org.slavicmyths.chud.ChudCreationJobs.create(player.createCommandSourceStack().withPermission(4),"medium",r->{if(r==null){metrics.put("chud_failed",true);phase=99;}else{metrics.put("chud_ms",(System.nanoTime()-stageAt)/1_000_000);metrics.put("chud_entrance",r.entrance().toShortString());phase=4;}});}
  else if(phase==2){var f=org.slavicmyths.bayun.BayunCreation.class.getDeclaredField("JOBS");f.setAccessible(true);if(!((Map<?,?>)f.get(null)).containsKey(w))throw new IllegalStateException("Bayun finished without a site");}
  else if(phase==4){stop(server,"PASS");}
  else if(phase==99)stop(server,"FAIL chud");
 }catch(Exception failure){metrics.put("error",failure.toString());failure.printStackTrace();stop(server,"FAIL");}}
 static void stop(MinecraftServer server,String result){metrics.put("result",result);metrics.put("ticks",ticks);metrics.put("peak_tick_ms",peak/1_000_000.);var sorted=new ArrayList<>(tickTimes);java.util.Collections.sort(sorted);if(!sorted.isEmpty()){metrics.put("p95_tick_ms",sorted.get((int)Math.min(sorted.size()-1,sorted.size()*.95))/1_000_000.);metrics.put("p99_tick_ms",sorted.get((int)Math.min(sorted.size()-1,sorted.size()*.99))/1_000_000.);}stopping=System.nanoTime();System.out.println("NORMAL_PROBE "+metrics);server.halt(false);}
 @SubscribeEvent public static void stopped(ServerStoppedEvent e){if(!enabled())return;metrics.put("shutdown_ms",(System.nanoTime()-stopping)/1_000_000);try{Files.writeString(Path.of("normal-probe.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(metrics));System.out.println("NORMAL_PROBE_FINAL "+metrics);}catch(Exception failure){throw new RuntimeException(failure);}}
}
